 "content": "def transform(grid):
    """Fill a complete isosceles triangle outlined by equal-color diagonal sides."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for dr in (-1, 1):
                depth = 0
                while True:
                    rr = r + dr * (depth + 1)
                    left = c - depth - 1
                    right = c + depth + 1
                    if not (0 <= rr < h and 0 <= left < w and 0 <= right < w):
                        break
                    if grid[rr][left] != color or grid[rr][right] != color:
                        break
                    depth += 1
                if depth == 0:
                    continue
                # Only complete triangles are meaningful: both sides must
                # arrive at the same boundary row together. This rejects
                # truncated, one-sided wedges in sparse fields.
                end_r = r + dr * depth
                next_r = end_r + dr
                if 0 <= next_r < h:
                    continue
                for d in range(1, depth + 1):
                    rr = r + dr * d
                    for cc in range(c - d + 1, c + d):
                        if grid[rr][cc] == 0:
                            out[rr][cc] = 2
    return out
